'use strict';
const C=window.JH,$=s=>document.querySelector(s),esc=C.escape,KEY='jh-planning-v1';
let projects=[],activeId=null,step=0,question=0,textPage=0,textSlices=[],homeTab='projects',homePage=0,docPage=0,docVersion='draft',docPages=[],broken=false,timer;
const now=()=>new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});
try{const data=localStorage.getItem(KEY);if(data)projects=C.parseBackup(data);}catch{broken=true;}
if(!broken&&projects.length<50&&!projects.some(p=>p.id===rewardCase.id)){
 const previous=projects;projects=[...projects,C.safeProject(rewardCase)];
 if(!persist())projects=previous;
}
const current=()=>projects.find(p=>p.id===activeId);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function persist(){if(broken){$('#save-status').textContent='원본 보존 · 읽기 오류';return false;}try{localStorage.setItem(KEY,JSON.stringify({format:KEY,projects}));$('#save-status').textContent='이 브라우저에 저장됨';return true;}catch{$('#save-status').textContent='저장 실패 · 백업 필요';toast('저장하지 못했습니다. 백업으로 현재 내용을 보존해 주세요.');return false;}}
const questions=[
 ['name','industry','target','problem','importance','evidence','assumption','goal'],
 ['c0name','c0action','c0basis','c1name','c1action','c1basis','c2name','c2action','c2basis','selected','reason','exclude','message','channel','action'],
 ['metric','unit','baseline','targetValue','definition','source','start','end','rule'],
 ['revisionReason','document']
];
const hints={name:'이 기획을 한눈에 구분할 수 있는 이름을 적어 주세요.',industry:'산업을 정하지 않아도 시작할 수 있습니다.',target:'사람과 상황을 함께 적어 주세요. 누구에게 필요한가요?',problem:'관찰한 어려움을 적습니다. 원인에 대한 추측은 가정으로 구분해 주세요.',importance:'이 문제로 어떤 행동이나 기회를 놓치고 있나요?',evidence:'직접 들은 말·관찰·출처를 남깁니다. 아직 없다면 미확인이라고 적어 주세요.',assumption:'아직 검증하지 않은 원인이나 기대를 적어 주세요.',goal:'무엇을 알게 하고, 어떤 행동을 이끌고 싶나요?',reason:'다른 후보 대신 이 방향을 선택한 이유를 남깁니다.',exclude:'이번에 하지 않을 일을 정해 범위를 지킵니다.',message:'상대에게 전할 핵심 가치와 약속을 적어 주세요.',channel:'이번에는 한 채널에 집중해 보세요.',action:'무엇을 만들고 어떤 행동을 요청할지 적습니다.',metric:'성공을 확인할 지표 하나를 먼저 정합니다.',unit:'핵심 지표를 셀 때 사용하는 단위입니다.',baseline:'아직 측정하지 않았다면 비워 두세요. 0과 미확인은 다릅니다.',targetValue:'목표는 달성한 성과가 아니라 앞으로 확인할 기준입니다.',definition:'무엇을 포함·제외할까요? 비율이면 분자와 분모도 적어 주세요.',source:'자료를 어디에서 누가 확인할지 정합니다.',start:'실행 결과를 확인하기 시작할 날짜입니다.',end:'시작일보다 빠르지 않게 정해 주세요.',rule:'어떤 결과에서 유지·수정·중단할지 적습니다.',revisionReason:'처음 확정한 이유 또는 이전 버전에서 바꾼 점과 이유를 적습니다.'};
function candidateKey(key){const m=/^c([0-2])(name|action|basis)$/.exec(key);return m?{index:Number(m[1]),key:m[2]}:null;}
function title(key){const c=candidateKey(key);return c?'후보 '+(c.index+1)+' · '+{name:'방향 이름',action:'실행 내용',basis:'근거와 제약'}[c.key]:key==='selected'?'이번에 실행할 방향을 선택하세요.':C.fields[key];}
function value(key){const c=candidateKey(key);return c?current().candidates[c.index][c.key]:current()[key];}
function setValue(key,v){const c=candidateKey(key);if(c)current().candidates[c.index][c.key]=v;else current()[key]=v;current().updated=now();persist();}
function keyNow(){return questions[step][question];}
function sidebar(){const p=current();$('#breadcrumb').textContent=p?'작업실 / '+(p.name||'이름 없는 기획'):'작업실 / 내 프로젝트';$('#side-projects').innerHTML=projects.slice(-3).reverse().map(x=>`<button class="side-project ${x.id===activeId?'active':''}" data-open="${esc(x.id)}" title="${esc(x.name)}">${esc(x.name||'이름 없는 기획')}</button>`).join('');}
function pageControls(page,count,attr){return `<div class="pager"><button ${page===0?'disabled':''} ${attr}="-1" aria-label="이전 페이지">←</button><span>${page+1} / ${Math.max(count,1)}</span><button ${page+1>=count?'disabled':''} ${attr}="1" aria-label="다음 페이지">→</button></div>`;}
function home(){activeId=null;sidebar();const list=homeTab==='projects'?projects:examples;const size=innerWidth<=640||innerHeight<=440?1:2;const count=Math.max(1,Math.ceil(list.length/size));homePage=Math.min(homePage,count-1);const cards=list.slice(homePage*size,(homePage+1)*size);$('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">JH PLANNING STUDIO</div><h1>좋은 기획은<br><em>이유</em>에서 시작합니다.</h1><p>흩어진 생각을 문제, 지표, 문서로 연결하세요.<br>무엇을 왜 해야 하는지 설명할 수 있도록.</p><button class="button primary" data-new>내 프로젝트 기획하기 <span>→</span></button></div><div class="method"><div><div class="num">01</div><strong>문제 정의</strong><p>누구의 문제를<br>왜 해결하나요?</p></div><div><div class="num">02</div><strong>성공 지표</strong><p>어떤 변화로<br>성공을 확인하나요?</p></div><div><div class="num">03</div><strong>기획 문서</strong><p>선택한 방향과<br>그 이유를 남깁니다.</p></div></div></section><section class="home-library"><div class="library-head"><div class="tab-switch" role="tablist" aria-label="프로젝트 목록"><button role="tab" aria-selected="${homeTab==='projects'}" class="${homeTab==='projects'?'active':''}" data-home-tab="projects">내 프로젝트 ${projects.length}</button><button role="tab" aria-selected="${homeTab==='examples'}" class="${homeTab==='examples'?'active':''}" data-home-tab="examples">가상 예시</button></div><span class="small-note">${homeTab==='examples'?'모든 내용·수치는 가상':'한 화면에서, 한 기획씩'}</span></div><div class="card-grid">${cards.length?cards.map(x=>{const example=homeTab==='examples';return `<button class="card" ${example?'data-example="'+examples.indexOf(x)+'"':'data-open="'+esc(x.id)+'"'}><span class="badge ${example||x.example?'example':''}">${example||x.example?'가상 예시':'내 기획'} · ${esc(x.industry||'산업 미지정')}</span><h3 title="${esc(x.name)}">${esc(x.name||'이름 없는 기획')}</h3><p>${esc(example?x.summary:x.goal||'문제를 정의하고 첫 방향을 정해 보세요.')}</p><div class="card-meta"><span>${example?'산업을 넘어, 기획하는 방법':x.revisions.length?'확정본 '+x.revisions.length+'개 보존':'작성 중인 기획'}</span><span class="arrow">↗</span></div></button>`}).join(''):'<div class="empty"><div><h3>첫 기획을 시작해 볼까요?</h3><p>새 프로젝트를 만들거나 가상 예시를 확인하세요.</p></div><button class="button" data-new>새 프로젝트 ＋</button></div>'}</div>${pageControls(homePage,count,'data-home-page')}</section>`;if(broken)toast('기존 기록을 읽지 못했습니다. 원본은 보존하며 백업으로 내려받을 수 있습니다.');}
function note(){const p=current(),missing=new Set(C.issues(p).map(e=>e.key)).size,total=C.required.length+1;return `<aside class="planning-note"><div class="eyebrow">PLANNING NOTE</div><h2>무엇을<br>왜 해야 하나?</h2><p>좋은 기획의 중심은<br>결과물보다 그 이유입니다.</p><div class="large-num">0${step+1}</div><p>${['문제를 좁히면<br>다음 선택이 분명해집니다.','다른 방향과 비교하고<br>선택한 이유를 남기세요.','측정할 기준이 있어야<br>다음 행동을 결정할 수 있습니다.','판단이 모이면<br>하나의 실행 문서가 됩니다.'][step]}</p><div class="note-progress"><div class="progress-label"><span>필수 입력·형식</span><strong>${Math.max(0,total-missing)} / ${total}</strong></div><div class="progress-line"><div style="width:${Math.max(0,(total-missing)/total*100)}%"></div></div><p>실제 효과와 기획의 타당성은<br>별도로 확인해야 합니다.</p></div></aside>`;}
function fieldBody(key){if(key==='selected')return `<div class="question-title"><label>이번에 실행할 방향을 선택하세요.</label></div><p class="question-hint">이름과 실행 내용이 있는 후보를 선택하세요. 상세 내용은 작성 항목에서 수정합니다.</p><div class="choice-grid">${current().candidates.map((c,i)=>`<button class="choice-card ${current().selected===String(i)?'selected':''}" data-pick="${i}" aria-pressed="${current().selected===String(i)}"><span class="number">0${i+1}</span><strong>${esc(c.name||'후보 이름 미작성')}</strong><p>${esc(c.action||'실행 내용 미작성')}</p><span>${current().selected===String(i)?'선택한 방향':'이 방향 선택'}</span></button>`).join('')}</div>`;
 const optional=['industry','assumption','exclude','baseline'].includes(key)||candidateKey(key);const v=value(key);let control;
 if(key==='unit')control='<select class="control" id="field-control" aria-describedby="field-hint" data-field="unit">'+['건','명','%','원','회','일'].map(u=>`<option ${v===u?'selected':''}>${u}</option>`).join('')+'</select>';
 else if(['name','industry','channel','metric','baseline','targetValue','start','end'].includes(key)||candidateKey(key)?.key==='name')control=`<input id="field-control" aria-describedby="field-hint" data-field="${key}" ${['baseline','targetValue'].includes(key)?'type="number" min="0" step="any"':key==='start'||key==='end'?'type="date"':'type="text" maxlength="10000"'} value="${esc(v)}" placeholder="${key==='baseline'?'미측정이면 비워 두세요':'여기에 작성해 주세요'}">`;
 else control=`<textarea id="field-control" data-field="${key}" aria-describedby="field-hint" placeholder="여기에 생각과 근거를 작성해 주세요." spellcheck="false"></textarea><div class="field-page-nav"><span id="text-page-label">내용 1 / 1</span><button data-text-page="-1" aria-label="이전 내용 페이지">←</button><button data-text-page="1" aria-label="다음 내용 페이지">→</button></div>`;
 return `<div class="question-title"><label for="field-control">${esc(title(key))}</label><span class="optional">${optional?'선택':'필수'}</span></div><p id="field-hint" class="question-hint">${hints[key]||'가능한 실행과 근거·작업량·제약을 함께 생각해 보세요.'}</p>${control}`;}
function workspace(){const p=current();if(!p)return home();sidebar();const key=keyNow();$('#main').innerHTML=`<div class="workspace-head"><div><span class="badge ${p.example?'example':''}">${p.example?'가상 예시 · 실제 고객·성과 아님':'내 기획'}</span><span class="meta">${esc(p.industry||'산업 미지정')}</span><h1 title="${esc(p.name)}">${esc(p.name||'이름 없는 기획')}</h1></div><button class="button" id="back-home">← 목록</button></div><nav class="steps" aria-label="기획 단계">${['문제 정의','방향과 선택','성공 지표','최종 문서'].map((t,i)=>`<button data-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}><span>0${i+1}</span>${t}</button>`).join('')}</nav><div class="work-layout"><section class="editor ${key==='document'?'document-mode':''}"><div class="editor-top"><span class="eyebrow">STEP 0${step+1}</span><select id="question-select" aria-label="작성 항목">${questions[step].map((k,i)=>`<option value="${i}" ${i===question?'selected':''}>${i+1}. ${k==='document'?'문서 미리보기':title(k)}</option>`).join('')}</select></div>${key==='document'?docBody():`<div class="editor-body">${fieldBody(key)}</div><div class="editor-bottom"><button class="button" data-question="-1">← 이전</button><span>${question+1} / ${questions[step].length} 항목</span><button class="button primary" data-question="1">${step===3?'문서 미리보기':'다음'} →</button></div>`}</section>${note()}</div>`;if(key==='document')requestAnimationFrame(fitDocument);else if($('#field-control')?.tagName==='TEXTAREA')requestAnimationFrame(fitText);}
function fitText(){const input=$('#field-control');if(!input||input.tagName!=='TEXTAREA')return;const style=getComputedStyle(input),width=input.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),height=input.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);const cols=Math.max(4,Math.floor(width/(parseFloat(style.fontSize)*.62))),rows=Math.max(1,Math.floor(height/parseFloat(style.lineHeight))-1);textSlices=C.pageText(value(keyNow()),cols,rows);textPage=Math.min(textPage,textSlices.length-1);const slice=textSlices[textPage];const trailing=/\n+$/.exec(slice.text)?.[0].length||0;slice.editEnd=slice.end-trailing;input.value=slice.text.slice(0,slice.text.length-trailing);$('#text-page-label').textContent='내용 '+(textPage+1)+' / '+textSlices.length;$('[data-text-page="-1"]').disabled=textPage===0;$('[data-text-page="1"]').disabled=textPage+1>=textSlices.length;}
function documentHtml(){const p=current();return docVersion==='draft'?C.report(p):p.revisions.find(r=>String(r.version)===docVersion)?.html||C.report(p);}
function docBody(){const p=current();const issues=C.issues(p);return `<div class="doc-actions"><select id="doc-version" aria-label="문서 버전"><option value="draft" ${docVersion==='draft'?'selected':''}>현재 초안</option>${p.revisions.map(r=>`<option value="${r.version}" ${docVersion===String(r.version)?'selected':''}>확정본 v${String(r.version).padStart(2,'0')}</option>`).join('')}</select><button class="button accent" id="finalize" ${docVersion!=='draft'?'disabled':''}>${docVersion==='draft'?'기획서 확정':'보존된 확정본'}</button><button class="button" id="download-doc">다운로드</button><button class="button" id="print">인쇄 / PDF</button></div><div class="doc-body">${docVersion==='draft'&&issues.length?`<div class="error-note"><span>확정 전 ${issues.length}개 항목 확인</span><button id="first-error">미작성 항목으로 →</button></div>`:''}<div class="paper-head"><strong>JH 기획 · 기획 제안서</strong><span>${p.example?'가상 예시 · ':''}${docVersion==='draft'?'작성 중 초안':'확정본 v'+docVersion}</span></div><div class="doc-page" id="doc-page" aria-live="polite"></div><div class="pager"><button data-doc-page="-1" aria-label="이전 문서 페이지">←</button><span id="doc-page-label"></span><button data-doc-page="1" aria-label="다음 문서 페이지">→</button></div></div>`;}
function fitDocument(){const box=$('#doc-page');if(!box)return;const source=document.createElement('div');source.innerHTML=documentHtml();const entries=[];source.querySelectorAll('section').forEach(section=>{const heading=section.querySelector('h3')?.textContent||'';section.querySelectorAll('dt').forEach(dt=>entries.push({heading,label:dt.textContent,text:dt.nextElementSibling?.textContent||''}));});const notice=source.querySelector('.doc-notice');if(notice)entries.push({heading:'확인 범위',label:'문서 안내',text:notice.textContent});const font=parseFloat(getComputedStyle(box).fontSize),cols=Math.max(5,Math.floor(box.clientWidth/(font*.62)));let html='';docPages=[];
 // ponytail: use actual rendered height to pack entries; no document scrolling or shortened downloads.
 for(const entry of entries){const chunks=C.pageText(entry.text,cols,Math.max(1,Math.floor((box.clientHeight-56)/(font*1.6))-1));for(let i=0;i<chunks.length;i++){const block=`<div class="doc-entry"><h3>${esc(entry.heading)}</h3><strong>${esc(entry.label)}${chunks.length>1?' · '+(i+1)+'/'+chunks.length:''}</strong><p>${esc(chunks[i].text)}</p></div>`;box.innerHTML=html+block;if(box.scrollHeight>box.clientHeight+1&&html){docPages.push(html);html=block;}else html+=block;}}
 if(html)docPages.push(html);if(!docPages.length)docPages=['<p>아직 작성한 문서가 없습니다.</p>'];docPage=Math.min(docPage,docPages.length-1);showDocPage();}
function showDocPage(){$('#doc-page').innerHTML=docPages[docPage];$('#doc-page-label').textContent=(docPage+1)+' / '+docPages.length+' 쪽';$('[data-doc-page="-1"]').disabled=docPage===0;$('[data-doc-page="1"]').disabled=docPage+1>=docPages.length;}
function openProject(id){activeId=id;step=0;question=0;textPage=0;docVersion='draft';docPage=0;workspace();}
function jumpError(){const e=C.issues(current())[0];if(!e)return;step=C.steps[e.key]??0;question=Math.max(0,questions[step].indexOf(e.key));textPage=0;workspace();requestAnimationFrame(()=>{$('#field-control')?.classList.add('field-invalid');$('#field-control')?.focus();});toast(e.message);}
function newProject(name,industry,build){if(broken){toast('기존 자료 읽기 오류가 있어 새 저장을 중단했습니다. 먼저 원본을 백업해 주세요.');return;}if(projects.length>=50){toast('최대 50개 프로젝트를 보관할 수 있습니다.');return;}const p=build?build():C.blank(name,industry);p.id=crypto.randomUUID();p.updated=now();projects.push(p);persist();openProject(p.id);}
function download(text,name,type='text/html;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function htmlFile(body){return '<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JH 기획 · 기획서</title><style>body{font:15px/1.7 Arial,"Malgun Gothic",sans-serif;color:#203438;max-width:820px;padding:40px 24px;margin:auto}h2{font-size:28px}.eyebrow,.doc-meta{font-size:12px;color:#5d706f}.report-header{border-bottom:2px solid #173436;padding-bottom:24px}section{padding-top:24px;break-inside:avoid}dt{font-size:13px;font-weight:bold;color:#5d706f;margin-top:16px}dd{margin:6px 0;white-space:pre-wrap;overflow-wrap:anywhere}.doc-notice{background:#eef3e8;padding:20px;margin-top:24px;font-size:12px}</style></head><body>'+body+'</body></html>';}
function finalize(){const p=current();if(C.issues(p).length){jumpError();return;}if(p.revisions.length>=30){toast('최대 30개 확정본을 보관할 수 있습니다.');return;}const snapshot=JSON.parse(JSON.stringify({...p,revisions:[]})),version=p.revisions.length+1;p.revisions.push({version,date:now(),reason:p.revisionReason,snapshot,html:C.report(snapshot,version)});if(!persist()){p.revisions.pop();return;}docVersion=String(version);docPage=0;workspace();toast('확정본 v'+String(version).padStart(2,'0')+'을 보존했습니다.');}
document.addEventListener('input',e=>{if(!current()||!e.target.dataset.field)return;const input=e.target,key=input.dataset.field;if(input.tagName==='TEXTAREA'){const slice=textSlices[textPage]||{start:0,end:value(key).length};const text=value(key).slice(0,slice.start)+input.value+value(key).slice(slice.editEnd??slice.end);if(text.length>10000){toast('한 항목에 최대 10,000자까지 보관합니다.');fitText();return;}setValue(key,text);slice.editEnd=slice.start+input.value.length;if(!e.isComposing&&input.scrollHeight>input.clientHeight+1){const caret=input.selectionStart;fitText();input.setSelectionRange(Math.min(caret,input.value.length),Math.min(caret,input.value.length));}}else setValue(key,input.value);});
document.addEventListener('compositionend',e=>{if(e.target.id==='field-control'&&e.target.tagName==='TEXTAREA')fitText();});
document.addEventListener('change',e=>{if(e.target.id==='question-select'){question=Number(e.target.value);textPage=0;workspace();}else if(e.target.id==='doc-version'){docVersion=e.target.value;docPage=0;workspace();}else if(e.target.dataset.field==='unit')setValue('unit',e.target.value);});
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.hasAttribute('data-new')){$('#new-dialog').showModal();$('#new-name').focus();}
 else if(el.dataset.open)openProject(el.dataset.open);
 else if(el.dataset.example!==undefined)newProject('','',()=>examples[Number(el.dataset.example)].build());
 else if(el.dataset.homeTab){homeTab=el.dataset.homeTab;homePage=0;home();}
 else if(el.dataset.homePage){homePage+=Number(el.dataset.homePage);home();}
 else if(el.dataset.step!==undefined){step=Number(el.dataset.step);question=0;textPage=0;docPage=0;workspace();}
 else if(el.dataset.question){const direction=Number(el.dataset.question);if(direction===1&&question+1===questions[step].length){if(step<3){step++;question=0;}}else if(direction===-1&&question===0){if(step>0){step--;question=questions[step].length-1;}else return home();}else question+=direction;textPage=0;workspace();$('#question-select')?.focus();}
 else if(el.dataset.textPage){textPage+=Number(el.dataset.textPage);fitText();}
 else if(el.dataset.docPage){docPage+=Number(el.dataset.docPage);showDocPage();}
 else if(el.dataset.pick!==undefined){setValue('selected',el.dataset.pick);workspace();$('[data-pick="'+el.dataset.pick+'"]').focus();}
 else if(['home-link','home-button','back-home'].includes(el.id)){e.preventDefault();home();}
 else if(el.id==='cancel-new')$('#new-dialog').close();
 else if(el.id==='first-error')jumpError();
 else if(el.id==='finalize')finalize();
 else if(el.id==='download-doc'){const p=current();download(htmlFile(documentHtml()),(p.name||'기획서').replace(/[<>:"/\\|?*\x00-\x1f]/g,'-').slice(0,70)+'-'+p.id.slice(0,8)+'-'+(docVersion==='draft'?'초안-'+Date.now():'v'+String(docVersion).padStart(2,'0'))+'.html');toast('전체 기획서를 내려받았습니다.');}
 else if(el.id==='print'){$('#print-area').innerHTML=documentHtml();window.print();}
 else if(el.hasAttribute('data-backup')){download(broken?localStorage.getItem(KEY)||'':JSON.stringify({format:KEY,projects},null,2),'JH-기획-백업-'+Date.now()+'.json','application/json');toast('현재 기록을 백업했습니다.');}
 else if(el.hasAttribute('data-restore'))$('#restore-file').click();
});
$('#new-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#new-name').value.trim();if(!name)return;newProject(name,$('#new-industry').value.trim());$('#new-dialog').close();$('#new-form').reset();});
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('10MB 이하의 백업을 선택해 주세요.');if(broken)throw Error('원본 기록을 먼저 보존해 주세요.');const imported=C.parseBackup(await file.text()),ids=new Set(projects.map(p=>p.id)),added=imported.filter(p=>!ids.has(p.id));if(projects.length+added.length>50)throw Error('최대 50개 프로젝트를 보관할 수 있습니다.');const previous=projects;projects=[...projects,...added];if(!persist()){projects=previous;throw Error('저장 실패로 복원을 취소했습니다.');}home();toast(added.length+'개 추가, 기존 번호는 보존했습니다.');}catch(err){toast('복원 중단: '+err.message);}e.target.value='';});
function refit(){if(current()){if(keyNow()==='document')fitDocument();else if($('#field-control')?.tagName==='TEXTAREA')fitText();}else home();}
window.addEventListener('resize',refit);
new ResizeObserver(refit).observe($('#main'));
document.fonts.ready.then(refit);
home();if(broken)$('#save-status').textContent='원본 보존 · 읽기 오류';else if(projects.length)$('#save-status').textContent='이 브라우저에 저장됨';
